-- place, latitude, longitude, travel month, challenge, lesson, advice, feed order.
insert into public.stories as s
  (id, destination_id, title, body, category, place_name, latitude, longitude,
   travel_month, challenge, lesson, advice, status, published_at, is_demo, source)
select v.id::uuid, d.id, v.title, v.body, v.category, v.place_name, v.latitude, v.longitude,
       v.travel_month::smallint, v.challenge, v.lesson, v.advice,
       'published', now() - make_interval(mins => v.ord), false, 'editorial'
from (values
  ('0e0ba35c-640e-5694-9a4c-619a072b1fbb', 'manali/atal-tunnel-queue', 'manali', 'The tunnel is quick; the queue to reach it isn''t', 'The Atal Tunnel turns the drive towards Lahaul into a short hop, which is why so many day-trippers head that way at once. On busy weekends the slow part is the road from Manali to the south portal, not the tunnel itself.', 'transport', 'Atal Tunnel south portal', 32.3687, 77.1683, null, null, 'Leave Manali early, before the day-trip traffic builds.', 'Carry water and a snack in the car, and keep the return time flexible in case of a jam near Solang.', 1),
  ('efcbdc03-6760-50bd-a312-5def656cb776', 'amritsar/golden-temple-head-cover', 'amritsar', 'Bring something to cover your head', 'Everyone covers their head inside the Golden Temple complex and leaves shoes at the free shoe counters. Scarves are usually available at the entrance, but having your own saves a scramble.', 'local_customs', 'Harmandir Sahib', 31.62, 74.8765, null, null, 'Carry a scarf or bandana and wear shoes that are easy to take off.', null, 2),
  ('ffa3acec-4fd0-5180-9b3c-b1e8733b03a3', 'morni-hills/weekend-traffic', 'morni-hills', 'Close to the city means busy on Sundays', 'Morni is an easy drive from Chandigarh and Panchkula, so winter Sundays bring a stream of cars up a narrow, winding road. Weekdays are quiet enough to hear the birds.', 'transport', 'Panchkula–Morni road', 30.69, 77, null, null, 'Visit on a weekday if you want the hills to yourself.', null, 3),
  ('762195bb-b237-5a98-9b4a-38cb792b3bfc', 'valley-of-flowers/same-day-return', 'valley-of-flowers', 'You can''t camp inside the valley', 'Visitors enter the park from Ghangaria for the day and must come back out the same day. The valley goes much further than most people manage to walk, so the return time sets how far you get.', 'planning', 'Valley of Flowers entry', 30.7085, 79.6053, null, 'Starting late leaves only a short stretch of the valley to see.', 'Spend the night at Ghangaria and enter as soon as the gate opens.', null, 4),
  ('d8fd05fd-7e2d-52c0-9b24-ea6756d1a4a2', 'agra/taj-friday', 'agra', 'The Taj Mahal is closed on Fridays', 'The Taj is closed to general visitors every Friday for prayers. A weekend trip from Delhi that arrives Thursday night and plans the Taj for Friday morning loses its main event.', 'planning', 'Taj Mahal', 27.1751, 78.0421, null, null, 'Check the day of the week before you fix the Agra dates.', 'Sunrise slots are popular; the east gate is usually the least crowded approach.', 5),
  ('3050c7a8-265d-5390-876b-e783d9fee656', 'jaipur/composite-ticket', 'jaipur', 'Look at the composite ticket before buying singles', 'Jaipur has a composite ticket that covers several monuments, including Amer and Nahargarh. Visitors who buy individual tickets at the first gate sometimes realise later that the combined pass would have suited their plan.', 'costs', 'Amer Fort', 26.9855, 75.8513, null, null, 'Decide your monument list first, then pick the ticket.', null, 6),
  ('240a52bd-f60c-5d10-8a5d-71901e391ff6', 'delhi/red-fort-monday', 'delhi', 'Red Fort takes Mondays off', 'The Red Fort is closed on Mondays. An Old Delhi day built around it falls flat if Monday is the only free day in a short trip.', 'planning', 'Red Fort', 28.6562, 77.241, null, null, 'Put the Red Fort on a different day and use Monday for places that stay open.', null, 7),
  ('26c2d02c-0581-5d53-9210-7dad8ada2386', 'chandigarh/sector-grid', 'chandigarh', 'Learn the sector numbers and the city makes sense', 'Chandigarh is laid out in numbered sectors separated by wide roads, and locals give directions by sector. Long blocks between roundabouts mean that places that look close can be a long, sunny walk apart.', 'transport', 'Sector 17', 30.741, 76.782, null, null, 'Use sector numbers when asking for directions, and take an auto between sectors.', null, 8),
  ('b0ba9844-71d9-5b6b-a1d1-77f72ee66a0b', 'srinagar/shikara-fare', 'srinagar', 'Fix the shikara route, not just the price', 'Shikara rides on Dal Lake are offered from numbered ghats along the boulevard. A ride can mean a quick loop or a long tour with shop stops, so the same price buys very different trips.', 'costs', 'Dal Lake ghats', 34.09, 74.835, null, null, 'Agree on the duration, route and stops before you get in.', null, 9),
  ('8fd06c98-324e-5e06-a17d-8b02cbae8764', 'leh/permits-fees', 'leh', 'Sort permits and fees before the long drives', 'Trips to Nubra, Pangong and other areas beyond Leh involve local permit or registration rules and environment fees, and the requirements have changed over the years. Taxi drivers will ask for the paperwork at the start.', 'planning', 'Leh', 34.1642, 77.5848, null, null, 'Check current rules with the Ladakh administration or your taxi union a day ahead.', null, 10),
  ('a084815c-3f35-55dd-81a5-61f8efd7c874', 'nalanda/ruins-shade', 'nalanda', 'There''s almost no shade among the ruins', 'The excavated site is large and open, with brick monasteries and temples spread over a wide area. In the hotter months, midday here is draining.', 'packing', 'Nalanda Mahavihara', 25.1357, 85.444, null, null, 'Go early, with a hat and water.', null, 11),
  ('e6cc1214-a495-57bc-a9e1-e0d2981547a5', 'deoghar/shravani-mela', 'deoghar', 'Shravan month is a different Deoghar', 'During the Shravani Mela in the monsoon month of Shravan, huge numbers of kanwariyas walk to Deoghar carrying Ganga water. Roads, trains and the temple are at their busiest.', 'planning', 'Baba Baidyanath Dham', 24.492, 86.7, null, null, 'Visit outside Shravan for a calm darshan; plan carefully if you''re going for the mela itself.', null, 12),
  ('00d5ab3b-9e0a-5236-bccc-e8ccf3aa7d3d', 'koraput/haat-etiquette', 'koraput', 'A weekly market is not a photo set', 'The weekly haats around Koraput are working markets where communities trade produce and goods. Visitors with cameras pointed at people''s faces are not always welcome, and some groups prefer not to be photographed.', 'local_customs', 'Weekly haat near Koraput', 18.8135, 82.7123, null, null, 'Ask before photographing anyone, and accept a no.', 'Going with a local guide helps you understand what you''re seeing and how to behave.', 13),
  ('6bf8f4d6-c18f-58f3-8361-f2c50f7915e9', 'darjeeling/tiger-hill-dawn', 'darjeeling', 'Tiger Hill means a very early start', 'Sunrise jeeps to Tiger Hill leave town in the dark, and the viewpoint is crowded and cold while you wait. Whether the peaks appear depends entirely on the clouds that morning.', 'planning', 'Tiger Hill', 26.997, 88.286, null, null, 'Dress warmly, accept the gamble, and keep a second morning free if you can.', null, 14),
  ('a5c00510-6052-585d-9828-a4c0b8454d5b', 'gangtok/tsomgo-permit', 'gangtok', 'Tsomgo Lake needs a permit arranged in advance', 'Trips to Tsomgo Lake and Nathu La from Gangtok need permits, usually arranged through registered tour operators with ID copies a day ahead. Rules for foreign nationals differ.', 'planning', 'Tsomgo Lake', 27.375, 88.764, null, null, 'Hand over ID documents the day before so the permit is ready.', null, 15),
  ('b4ec3e04-6152-52cb-a194-11fee4b66680', 'kaziranga/monsoon-closure', 'kaziranga', 'The park closes during the monsoon', 'Kaziranga''s safari zones close during the monsoon floods, typically from late spring to autumn. Visitors arriving in those months find only the edges of the park open.', 'planning', 'Kohora (Central Range)', 26.5775, 93.1711, null, null, 'Plan Kaziranga between November and April, and check the official opening date.', null, 16),
  ('ee4e86ed-9497-5378-b625-c6ddf14237a2', 'tawang/ilp', 'tawang', 'Arrange your Inner Line Permit before the trip', 'Indian visitors need an Inner Line Permit to enter Arunachal Pradesh, and it''s checked at entry points. Foreign nationals need a separate Protected Area Permit.', 'planning', 'Tawang', 27.586, 91.859, null, null, 'Apply online before travelling and carry printed copies.', null, 17),
  ('04d8b7e4-a73e-5d99-98f5-5612c1641318', 'sohra/nongriat-steps', 'sohra', 'Nongriat is thousands of steps, down and back', 'The path from Tyrna to the double-decker root bridge at Nongriat is a long staircase into the valley, with thousands of uneven steps and some suspension bridges. Going down is the easy half.', 'activity', 'Double-decker root bridge, Nongriat', 25.24, 91.683, null, null, 'Start early, take your time, and save energy for the climb back.', 'Staying overnight in Nongriat village makes it a much gentler trip.', 18),
  ('e3403e80-709b-5809-bb5b-24fafb913b4b', 'loktak-lake/phumdi-homestay', 'loktak-lake', 'Stay near the lake to see it at dawn', 'Loktak''s floating vegetation islands look their best in the early morning, when fishermen are out and the water is still. A short afternoon visit from Imphal misses that.', 'activity', 'Sendra', 24.507, 93.781, null, null, 'Stay overnight nearby if you can.', null, 19),
  ('ff45ee28-70ea-5b21-9a16-4aa7f5881cdd', 'aizawl/sunday', 'aizawl', 'Sunday is a day of rest', 'Most shops, markets and many restaurants close on Sundays, when much of the city goes to church. Visitors who arrive on Saturday night expecting to shop on Sunday find quiet streets.', 'local_customs', 'Aizawl', 23.7271, 92.7176, null, null, 'Stock up on Saturday and plan a slow Sunday.', null, 20),
  ('e450ca2c-8a89-5655-886e-49c3a1983863', 'kohima/hornbill-booking', 'kohima', 'Hornbill Festival rooms vanish early', 'The Hornbill Festival runs in the first ten days of December at Kisama, outside Kohima. Rooms, homestays and taxis in and around Kohima book out well in advance.', 'planning', 'Kisama Heritage Village', 25.62, 94.12, 12, null, 'Book stay and transport months ahead, and carry your Inner Line Permit.', null, 21),
  ('fc0780e1-3f65-5cf9-bdd7-e3a388ce4305', 'unakoti/base-kailashahar', 'unakoti', 'Unakoti is far from Agartala', 'Unakoti is in the north of Tripura, a long road journey from Agartala. Trying to see it as a same-day return trip leaves very little time at the carvings.', 'transport', 'Kailashahar', 24.332, 92.005, null, null, 'Stay in Kailashahar or Dharmanagar and visit in the morning.', null, 22),
  ('3525fa12-0d08-5c71-b80f-3f224070a263', 'sri-vijaya-puram/light-show', 'sri-vijaya-puram', 'Book the Cellular Jail light and sound show', 'The evening light and sound show at the Cellular Jail is a highlight for many visitors, and seats are limited. Shows are sometimes cancelled in heavy rain.', 'planning', 'Cellular Jail', 11.6741, 92.748, null, null, 'Book on your first day and keep a backup evening.', null, 23),
  ('77acde24-5f2e-53f7-9228-f86362b47b4e', 'gandikota/canyon-heat', 'gandikota', 'The gorge is beautiful and very exposed', 'The rocks above the gorge have little shade, and the heat builds quickly from mid-morning. Sunset and sunrise are the comfortable times, and also the best light.', 'weather', 'Gandikota gorge viewpoint', 14.813, 78.287, null, null, 'See the gorge at the edges of the day and rest in between.', null, 24),
  ('9a708950-cf85-5db4-ab69-85e8c2e23953', 'warangal/ramappa-distance', 'warangal', 'Ramappa is a separate trip from Warangal', 'The UNESCO-listed Ramappa Temple lies a long drive from Warangal city. Fitting it into an afternoon after the fort and the Thousand Pillar Temple is a rush.', 'transport', 'Ramappa Temple', 18.259, 79.943, null, null, 'Give Ramappa its own half day, ideally in the morning.', null, 25),
  ('5dfc5586-ce88-5b7c-bf46-7ad8ac987eba', 'hampi/river-crossing', 'hampi', 'The river crossing isn''t always running', 'Hampi''s sites are split by the Tungabhadra, and the boat crossing to the Virupapur Gaddi and Anegundi side is suspended when the water is high. The road around takes much longer.', 'transport', 'Tungabhadra crossing', 15.339, 76.459, null, 'Staying on one bank and planning your days on the other can strand you.', 'Check whether the crossing is operating before choosing which side to stay on.', null, 26),
  ('725a9293-fcc3-5ca8-84b7-1c072ee51bf6', 'munnar/rain-alerts', 'munnar', 'Watch for district rain alerts in the monsoon', 'Heavy rain in the hills can bring landslides, and the district administration sometimes restricts night travel or closes viewpoints during alerts.', 'weather', 'Munnar', 10.0889, 77.0595, null, null, 'Check district alerts daily in the monsoon and drive the ghat roads in daylight.', null, 27),
  ('061a217b-0d1b-509d-b08e-3607b88ba3cf', 'ooty/mountain-railway', 'ooty', 'The mountain railway sells out early', 'The Nilgiri Mountain Railway''s rack section from Mettupalayam is slow, scenic and popular, with limited seats. In holiday season they go quickly.', 'transport', 'Mettupalayam station', 11.299, 76.935, null, null, 'Book as soon as reservations open for your date.', null, 28),
  ('dec5f518-b836-5e42-a344-f82ab1422076', 'anjuna/flea-market', 'anjuna', 'The flea market is a Wednesday, in season', 'Anjuna''s flea market runs on Wednesdays during the tourist season and doesn''t operate in the monsoon. A trip planned around it on another day finds an empty field.', 'planning', 'Anjuna flea market', 15.5735, 73.741, null, null, 'Check the day and season before planning around the market.', null, 29),
  ('5f6e0a40-a18d-5e2a-9f7f-72da531a9e13', 'puducherry/matrimandir', 'puducherry', 'The Matrimandir needs advance booking', 'Visitors can see the Matrimandir from a viewing point without booking, but entering the inner chamber requires advance arrangements through the Auroville visitor centre.', 'planning', 'Auroville', 12.006, 79.81, null, null, 'Book through the visitor centre if you want to go inside.', null, 30),
  ('148848aa-d646-5d13-a52d-e4706b1defbe', 'agatti/entry-permit', 'agatti', 'You need a permit to visit Lakshadweep', 'Visitors to Lakshadweep need an entry permit, and access is mainly through limited flights and ships. Unlike most destinations, you can''t decide to go next week.', 'planning', 'Agatti', 10.85, 72.19, null, null, 'Start the permit and travel arrangements well in advance.', null, 31),
  ('0ccb587e-5a0a-5c35-91f5-1ea52b912494', 'rann-of-kutch/white-rann-permit', 'rann-of-kutch', 'The White Rann needs a permit', 'Visitors to the White Rann need a permit, available online or at the checkpoint on the way. Queues at the counter build up in the afternoon before sunset.', 'planning', 'Bhirandiyara checkpoint', 23.73, 69.84, null, null, 'Get the permit online, or arrive at the checkpoint early.', null, 32),
  ('ea4e04eb-1b9a-557f-8127-e93782679529', 'ajanta-caves/monday', 'ajanta-caves', 'Ajanta is closed on Mondays', 'Ajanta is closed on Mondays and Ellora on Tuesdays. With the two sites a long way apart, the order you visit them in matters.', 'planning', 'Ajanta Caves', 20.5519, 75.7033, null, null, 'Plan Ajanta and Ellora around their weekly closing days.', 'Private vehicles stop at the visitor centre; shuttle buses run the last stretch to the caves.', 33),
  ('135fa29b-3740-5997-b840-d649088afca4', 'khajuraho/eastern-group', 'khajuraho', 'Rent a bicycle for the eastern and southern temples', 'The Western Group is compact and ticketed, but the eastern and southern temples are scattered around the village. Walking between them in the heat is slow.', 'transport', 'Eastern Group of Temples', 24.849, 79.935, null, null, 'A bicycle makes the outer temples an easy morning.', null, 34),
  ('864740a1-6b7d-5d53-8b48-6d3dc97c66a8', 'chitrakote/season-colour', 'chitrakote', 'The falls change completely with the season', 'In the monsoon Chitrakote is a wide, roaring, muddy-brown curtain. After the rains it slims into several clearer streams. Both are impressive, but they look like different places.', 'weather', 'Chitrakote Falls', 19.2066, 81.6994, null, null, 'Pick your season deliberately, and keep back from the edge in high water.', null, 35),
  ('5e5df7be-af83-58e1-b4ca-fdf78f3cc7af', 'diu/alcohol-border', 'diu', 'Diu''s rules end at the Gujarat border', 'Alcohol is sold in Diu, but Gujarat, which surrounds it, has prohibition. Carrying bottles back across the border can lead to serious trouble at checkpoints.', 'local_customs', 'Diu', 20.7144, 70.9874, null, null, 'Don''t take alcohol out of Diu into Gujarat.', null, 36),
  ('bec792ea-cd65-50ca-a230-4b69a14e2ff2', 'spiti-valley/kunzum-season', 'spiti-valley', 'Kunzum La isn''t open all year', 'The Manali side route into Spiti crosses Kunzum La, which is snowbound for a large part of the year. Outside the summer window, the only practical way in is the long road via Shimla and Kinnaur.', 'planning', 'Kunzum La', 32.3967, 77.6383, null, 'Itineraries built as a loop can fall apart if one pass is still closed.', 'Decide your direction into Spiti only after checking which passes are open that week.', null, 37),
  ('6e7b72ac-d381-5856-9685-f65eec42f92e', 'amritsar/golden-temple-night', 'amritsar', 'Go back after dark', 'Midday visits mean hot marble underfoot and the longest line to the inner sanctum. Early morning and late evening are calmer, and the temple reflected in the lit-up pool is a different sight.', 'planning', 'Harmandir Sahib', 31.62, 74.8765, null, null, 'Plan two short visits instead of one long midday one.', 'The marble walkways can be very hot in summer afternoons; carpets cover only some paths.', 38),
  ('6d298cbd-e0fc-5252-a362-577b65772b7d', 'morni-hills/tikkar-taal-supplies', 'morni-hills', 'Carry what you need for the day', 'Food stalls and fuel are limited once you leave the main road, and mobile coverage can be patchy in the valleys. A picnic-and-walk day works best when you bring the picnic.', 'planning', 'Tikkar Taal', 30.672, 77.052, null, null, 'Fill the tank and pack water and food before heading up.', null, 39),
  ('b3627519-12fd-5e5e-a26d-c2211b822646', 'valley-of-flowers/monsoon-bloom', 'valley-of-flowers', 'Peak flowers arrive with peak rain', 'The park is open only in the summer months, and the fullest blooms come during the monsoon. That''s also when landslides block the roads into Chamoli, sometimes for a day or more.', 'weather', 'Govindghat', 30.6146, 79.5594, null, null, 'Build at least one spare day into a monsoon trip here.', 'Pack a proper rain shell and shoes with grip; ponchos alone struggle on the climb to Ghangaria.', 40),
  ('4b63e78c-1321-595a-b1d4-a8ee2f999eb3', 'agra/fatehpur-sikri-guide', 'agra', 'Fatehpur Sikri deserves more than a stopover', 'Fatehpur Sikri is often squeezed in on the way to or from Agra, but the palace complex and the mosque are large and spread out. In an hour you see the gate and little else.', 'planning', 'Fatehpur Sikri', 27.0945, 77.6679, null, null, 'Give it at least half a day, ideally in the morning.', 'If you hire a guide, use one with an official licence from the ticket area.', 41),
  ('549e7780-61ba-5cc7-8e23-c32140920ec8', 'bundi/taragarh-monkeys', 'bundi', 'Taragarh belongs to the monkeys', 'The climb to Taragarh is steep, overgrown in places and home to a lot of monkeys, who know exactly what a plastic bag means. Some visitors carry a stick on the path.', 'safety', 'Taragarh Fort', 25.4425, 75.6436, null, null, 'Don''t carry food in your hands, and keep bags zipped.', 'Go in the morning with water, sturdy shoes and someone who knows the path.', 42),
  ('43542bed-b20f-5801-bf0c-4709d9d2c062', 'delhi/metro-rush', 'delhi', 'The Metro is fast, except at rush hour with luggage', 'The Delhi Metro is usually the quickest way across the city. At office rush hours interchange stations get very crowded, which is hard work with a suitcase.', 'transport', 'Rajiv Chowk Metro', 28.6328, 77.2197, null, null, 'Travel with big bags outside peak hours, or take a cab for that leg.', 'The first coach in the direction of travel is reserved for women.', 43),
  ('33332f90-1246-5c4d-971e-fb6429ebb273', 'chandigarh/rock-garden-time', 'chandigarh', 'The Rock Garden is a maze of its own', 'Nek Chand''s Rock Garden winds through narrow passages, courtyards and waterfalls. It takes longer than expected, and it''s next to Sukhna Lake, which people often want to add on.', 'planning', 'Rock Garden', 30.7525, 76.8072, null, null, 'Give the garden and the lake a whole afternoon.', null, 44),
  ('7507cd5b-efc4-5937-873b-27e485c8e9ed', 'srinagar/mughal-gardens-season', 'srinagar', 'Spring changes the gardens completely', 'Srinagar''s Mughal gardens look very different through the year. Spring blooms and autumn chinar colours are the famous seasons; in deep winter the fountains are off and it can be bitterly cold.', 'weather', 'Nishat Bagh', 34.1255, 74.8797, null, null, 'Match your expectations to the month, and pack warm if you come in winter.', null, 45),
  ('d4fb5b77-9659-5d0a-a69b-bc2f17312d71', 'leh/plastic-water', 'leh', 'Refill instead of buying bottles', 'Waste is hard to deal with in a cold desert, and plastic bottles pile up quickly. Many cafés and shops in Leh offer filtered water refills.', 'other', 'Leh Main Bazaar', 34.1645, 77.5853, null, null, 'Bring a sturdy bottle and use refill points.', null, 46),
  ('8c401165-5c59-59a1-9de1-fb7355452cbe', 'nalanda/museum-first', 'nalanda', 'See the museum before the ruins', 'Without context, the ruins can look like rows of similar brick walls. The site museum and a licensed guide turn them into lecture halls, dormitories and libraries.', 'activity', 'Nalanda Archaeological Museum', 25.137, 85.441, null, null, 'Start with the museum or a guide, then walk the site.', null, 47),
  ('81dda628-60ea-58bd-844a-b83f92e6c0b5', 'deoghar/temple-queue', 'deoghar', 'The queue is long and mostly standing', 'Even on ordinary days, the queue for darshan can mean a long time on your feet in a crowd. That''s hard for older visitors or anyone with mobility needs.', 'accessibility', 'Baba Baidyanath Dham', 24.492, 86.7, null, null, 'Ask about the temple''s current arrangements for elderly and differently-abled visitors.', null, 48),
  ('317e3a05-4fd3-55f6-828d-6a4543a70182', 'koraput/hill-roads', 'koraput', 'Distances in the hills take longer', 'Waterfalls, viewpoints and villages around Koraput are scattered across hilly roads. A list that looks like a single day on the map is often two.', 'transport', 'Koraput', 18.8135, 82.7123, null, null, 'Pick a few places and give each one time.', null, 49),
  ('8e9caa51-7d8d-5e15-9147-7cfd59141ac9', 'darjeeling/toy-train-joyride', 'darjeeling', 'Joy rides and full journeys are different tickets', 'The Darjeeling Himalayan Railway runs short joy rides from Darjeeling via Batasia Loop as well as longer journeys down the hill. Seats on both can sell out in season.', 'transport', 'Darjeeling station', 27.036, 88.263, null, null, 'Decide which ride you want and book it ahead.', null, 50),
  ('5b5edb61-72d1-581f-9db9-ba0e4404816c', 'gangtok/mg-marg-rules', 'gangtok', 'MG Marg is strict about litter and smoking', 'Gangtok''s MG Marg is a pedestrian promenade, and rules against littering and smoking are taken seriously. The town as a whole prides itself on being clean.', 'local_customs', 'MG Marg', 27.3294, 88.6122, null, null, 'Carry your rubbish until you find a bin.', null, 51),
  ('d4483213-2848-522f-8519-d54e11006e17', 'kaziranga/zones', 'kaziranga', 'Pick a zone, not just a safari', 'Kaziranga has several safari ranges, each with a different landscape and starting point. Staying near one range and booking another means an early drive.', 'activity', 'Bagori (Western Range)', 26.6, 93.13, null, null, 'Book safaris in the range closest to your stay, or plan the transfer time.', null, 52),
  ('82d69442-8f91-5c01-ad26-62692e4df45e', 'tawang/sela-snow', 'tawang', 'Sela Pass weather changes fast', 'The road to Tawang crosses Sela Pass at well over 4,000 m. Snow, fog and cold arrive quickly, even when the valleys below are mild.', 'weather', 'Sela Pass', 27.502, 92.108, null, null, 'Carry warm clothes in the car, not in the boot under everything else.', null, 53),
  ('ad2bd805-e9a8-5bb4-aca8-08e3c3f34fa7', 'sohra/rain-gear', 'sohra', 'Pack for rain, whatever the month', 'Sohra gets heavy rain for much of the year, and fog can hide the waterfalls for hours. Clear viewpoints are a matter of luck and patience.', 'packing', 'Nohkalikai Falls viewpoint', 25.276, 91.684, null, null, 'Carry a good rain jacket, quick-dry shoes and a flexible plan.', null, 54),
  ('3588f524-cd0a-5802-bbbf-543af8c8e6a7', 'loktak-lake/sangai', 'loktak-lake', 'Sangai deer are shy', 'Keibul Lamjao is the only natural home of the sangai, Manipur''s brow-antlered deer. They keep their distance on the floating grasslands.', 'activity', 'Keibul Lamjao National Park', 24.5, 93.833, null, null, 'Bring binoculars and visit in the early morning.', null, 55),
  ('a808ce62-79b2-574d-b381-53ac80176656', 'aizawl/ilp-airport', 'aizawl', 'Carry documents for the Inner Line Permit', 'Indian visitors from outside Mizoram need an Inner Line Permit, which is issued on arrival at the airport or can be applied for in advance. Without photos and ID copies, the counter takes longer.', 'planning', 'Lengpui Airport', 23.84, 92.62, null, null, 'Keep ID, a copy and a passport photo in your hand luggage.', null, 56),
  ('be948d89-36d1-5c1e-860d-cae253b82321', 'kohima/war-cemetery', 'kohima', 'The War Cemetery is a quiet place', 'The Kohima War Cemetery, on the site of a 1944 battle, is a place of remembrance. Visitors are expected to be quiet and respectful.', 'local_customs', 'Kohima War Cemetery', 25.667, 94.107, null, null, 'Treat it as a memorial, not a backdrop.', null, 57),
  ('f1097f9a-ee2f-5c08-96a4-57d8d01dc97d', 'unakoti/steps-carvings', 'unakoti', 'The best carvings are down a lot of steps', 'The largest reliefs sit in a ravine reached by long flights of steps. They can be slippery after rain.', 'accessibility', 'Unakoti rock carvings', 24.316, 92.07, null, null, 'Wear shoes with grip and take the steps slowly.', null, 58),
  ('96eb18e2-8ab1-5910-b45c-6bee080bc43b', 'sri-vijaya-puram/network-cash', 'sri-vijaya-puram', 'Don''t rely on your phone alone', 'Mobile data can be slow or unavailable outside the capital, which affects UPI payments and maps. Some islands have only a few ATMs.', 'costs', 'Sri Vijaya Puram', 11.6234, 92.7265, null, null, 'Carry cash and download offline maps before leaving the capital.', null, 59),
  ('6b5e12fe-d9fb-5eda-9383-2cfa5f9363ce', 'gandikota/supplies', 'gandikota', 'Gandikota is a village, not a town', 'Food and stays at Gandikota are limited, and the nearest town with more choice is Jammalamadugu. Arriving late without arrangements leaves few options.', 'planning', 'Gandikota fort', 14.815, 78.286, null, null, 'Book your stay and bring snacks and water.', 'If you''re camping, follow the rules of the designated site and leave nothing behind.', 60),
  ('27b91ff9-57c4-5134-a228-8efff802514b', 'warangal/fort-ruins', 'warangal', 'Warangal Fort is open ground', 'The fort''s famous gateways stand in a wide area of scattered ruins with little shade. It''s more of a walk than a building.', 'packing', 'Warangal Fort', 17.957, 79.614, null, null, 'Bring a hat and water, and go in the cooler part of the day.', null, 61),
  ('b0f9b90d-5fbe-516d-81df-7c4385616c53', 'hampi/two-days', 'hampi', 'One day in Hampi is mostly a blur', 'The ruins spread over a large area of boulders, temples and plantations. A day trip covers a few headline sights; the rest needs at least two days.', 'planning', 'Virupaksha Temple', 15.335, 76.459, null, null, 'Stay two or three nights and split the sites by area.', null, 62),
  ('2a82a0b1-d633-5111-a3f5-f9d286dd59e3', 'varkala/cliff-edge', 'varkala', 'The cliff path has edges without railings', 'The cliff-top walkway is lined with cafés, but parts of the edge have no barrier, and erosion has changed sections of the path. After dark, some stretches are poorly lit.', 'safety', 'North Cliff', 8.7378, 76.7036, null, null, 'Carry a torch at night and keep a step back from the edge.', null, 63),
  ('5697c94f-a644-5aa3-81ac-e144a16f10a6', 'ooty/epass', 'ooty', 'Check whether you need a vehicle e-pass', 'In recent seasons, vehicles entering the Nilgiris have needed an e-pass, introduced to manage tourist traffic. The rules have changed between seasons.', 'planning', 'Nilgiris district entry', 11.35, 76.79, null, null, 'Check the current requirement before you drive up.', null, 64),
  ('1e73f357-4cb1-5f8a-85c2-467cf01213fa', 'palolem/monsoon-goa', 'palolem', 'Monsoon Goa is green, rough and shut', 'In the monsoon, beach shacks are taken down, the sea is rough and swimming is restricted. It''s a lovely time for green landscapes, not a beach holiday.', 'weather', 'Palolem beach', 15.01, 74.023, null, null, 'Visit between November and April for the beach; come in the monsoon for the hinterland.', null, 65),
  ('1946a7ac-4036-5e3f-8616-446378b4454e', 'puducherry/promenade', 'puducherry', 'The promenade is best early or late', 'Goubert Avenue along the seafront is closed to traffic at certain times, and that''s when it''s at its best. At midday the sun bounces off the stone.', 'planning', 'Promenade Beach', 11.933, 79.835, null, null, 'Walk it at sunrise or in the evening.', null, 66),
  ('19420777-7ff6-59b8-9f80-a1754e6fbfef', 'agatti/island-rules', 'agatti', 'Island rules differ from the mainland', 'Lakshadweep has its own rules on alcohol, conduct and where visitors may go, and communities are conservative. Beachwear away from resort areas draws attention.', 'local_customs', 'Agatti lagoon', 10.84, 72.18, null, null, 'Read the island''s visitor guidelines and dress modestly in villages.', null, 67),
  ('efcb492c-d3db-5a75-b5ab-af7f333eb6d7', 'rann-of-kutch/season-wind', 'rann-of-kutch', 'The salt flat is a winter destination', 'The Rann is at its whitest in the dry winter months, after the monsoon water has evaporated. Nights on the flat are cold and windy even when days are warm.', 'weather', 'White Rann', 23.85, 69.66, null, null, 'Visit between November and February and carry a warm layer for the evening.', null, 68),
  ('0f222fd2-8b03-5fbc-87d2-c47e33ae4c9f', 'ellora-caves/kailasa-first', 'ellora-caves', 'Start with the Kailasa temple', 'Ellora''s caves stretch along a long escarpment, and the Kailasa temple is the one everyone comes for. By late morning it''s crowded and hot in the courtyard.', 'planning', 'Kailasa Temple (Cave 16)', 20.0244, 75.1793, null, null, 'See Kailasa first thing, then walk to the outer caves.', null, 69),
  ('25a2aecf-9429-5b5b-a9c1-448710bbaef5', 'khajuraho/summer-heat', 'khajuraho', 'Summer afternoons are fierce', 'Khajuraho gets very hot in summer, and the temples sit on open platforms. Stone floors are hot underfoot when shoes come off.', 'weather', 'Western Group of Temples', 24.852, 79.92, null, null, 'Visit in the early morning or late afternoon, and carry socks.', null, 70),
  ('0db8b863-31b3-52ff-bd12-12df7dc00985', 'chitrakote/boats', 'chitrakote', 'Boat rides depend on the water level', 'Small boats sometimes take visitors towards the base of the falls when the water is calm. In high water, these rides are stopped.', 'safety', 'Chitrakote Falls pool', 19.205, 81.7, null, null, 'Only take boats when they''re operating officially, and wear the life jacket.', null, 71),
  ('040f2ff7-67d1-57b4-9525-fca5d125c2cb', 'diu/fort-midday', 'diu', 'Explore the fort before midday', 'Diu Fort''s ramparts are exposed to sun and sea wind, with little shade. Late morning heat makes the walk tiring.', 'weather', 'Diu Fort', 20.714, 71, null, null, 'Go early and pair it with a shaded lunch in town.', null, 72),
  ('8f71a560-1e9f-5f57-be93-7555f7479630', 'spiti-valley/kaza-altitude', 'spiti-valley', 'Kaza sits higher than it feels on arrival', 'Kaza is around 3,800 m. Arriving straight from the plains and going for a monastery climb the same evening is a common way to spend the next day in bed with a headache.', 'activity', 'Kaza', 32.2276, 78.071, null, null, 'Gain height gradually and keep the first day in Kaza slow.', 'If you come via Kinnaur, a night in Kalpa or Nako helps. Follow medical advice for altitude rather than guessing.', 73),
  ('a9bf36c5-9bea-58c5-a164-7c355ebe73a9', 'amritsar/attari-early', 'amritsar', 'The border ceremony fills up long before it starts', 'The evening flag-lowering ceremony at Attari is popular, and the seating gallery fills well before the start. Bags are restricted at security, and the drive back to the city is slow when everyone leaves together.', 'planning', 'Attari border', 31.6047, 74.5732, null, 'Arriving close to the start time can mean standing far from the gate.', 'Reach Attari early and travel light.', null, 74),
  ('0fd1db65-a696-50f7-a5ba-445f0a056000', 'sultanpur-national-park/winter-birds', 'sultanpur-national-park', 'Come in winter, early, with binoculars', 'Migratory birds arrive in the cooler months, and the lake can look almost empty in the summer heat. Birds are most active in the early morning, well before school groups arrive.', 'weather', 'Sultanpur wetland', 28.463, 76.889, null, null, 'Time the visit for winter mornings.', 'A pair of binoculars makes a bigger difference here than a long camera lens.', 75),
  ('7994ce1a-2bcb-529f-a968-8a7d3184a372', 'rishikesh/rafting-season', 'rishikesh', 'Rafting has an off season', 'Commercial rafting pauses during the monsoon, when the Ganga runs high and fast. Plenty of people only find out on arrival, after building a weekend around it.', 'activity', 'Shivpuri rafting stretch', 30.1349, 78.3883, null, null, 'Check that rafting is operating for your dates before you travel.', null, 76),
  ('5193f60e-5a5c-5f32-b727-2c7161e2d49c', 'varanasi/manikarnika-photos', 'varanasi', 'The burning ghat isn''t a photo stop', 'Cremations take place around the clock at Manikarnika. Families are grieving there, and pointing a camera at funeral pyres is considered deeply disrespectful.', 'local_customs', 'Manikarnika Ghat', 25.3109, 83.0137, null, null, 'Watch quietly from a distance and keep your camera away.', null, 77),
  ('33233f5e-76d4-5d7d-b89e-025e7eaa088c', 'bundi/stepwells-slow', 'bundi', 'Bundi rewards a slow day, not a quick stop', 'Bundi is often squeezed between Jaipur and Udaipur as a half-day stop. Its stepwells, palace murals and old lanes sit close together but are best seen without a clock running.', 'planning', 'Raniji ki Baori', 25.44, 75.639, null, null, 'Stay overnight; the town is quietest in the early morning.', null, 78),
  ('355a6b7f-6b18-5cdf-bec5-f56510d9aac4', 'delhi/winter-air', 'delhi', 'Check the air quality in late autumn and winter', 'Smog often settles over Delhi in late autumn and early winter. On bad days, long outdoor walking tours can be unpleasant, especially for children, older travellers and anyone with asthma.', 'weather', 'India Gate', 28.6129, 77.2295, null, null, 'Keep indoor options in the plan and check air-quality readings each morning.', null, 79),
  ('081664be-ccca-5234-aa52-0b3ad1a45c7f', 'gulmarg/gondola-booking', 'gulmarg', 'Book gondola tickets online and early', 'The gondola is the main reason many people come to Gulmarg, and tickets are sold online through the official booking system. On busy days the slots sell out, and the upper phase can stop in bad weather.', 'planning', 'Gulmarg Gondola', 34.0505, 74.3858, null, null, 'Book in advance, go early, and keep a second day as backup.', null, 80),
  ('3af99e9b-23b3-5552-8060-da84fc12d795', 'leh/pangong-overnight', 'leh', 'Lake nights are colder than Leh', 'Pangong is higher than Leh and very exposed to wind. Even in summer, nights by the lake can be close to freezing, and camps don''t always have much heating.', 'weather', 'Pangong Tso', 33.918, 78.45, null, null, 'Pack a warm layer, gloves and a hat even for a summer night at the lake.', null, 81),
  ('bcd85bd0-ecea-5320-95b0-b87e788d07ce', 'bodh-gaya/mahabodhi-items', 'bodh-gaya', 'Check what you''re allowed to carry into the temple', 'The Mahabodhi complex has its own rules about phones, cameras and bags, and shoes are left outside. Visitors who arrive with a full daypack spend time going back and forth to deposit counters.', 'local_customs', 'Mahabodhi Temple', 24.6959, 84.9913, null, null, 'Carry as little as possible and read the entry rules at the gate.', null, 82),
  ('857a5b25-6968-5d5a-b43b-d4ed01a80574', 'netarhat/limited-rooms', 'netarhat', 'Netarhat has few places to stay', 'Netarhat is small and quiet, with a handful of government and private stays. On winter weekends and holidays, turning up without a booking can mean a long drive back down in the dark.', 'planning', 'Netarhat', 23.477, 84.266, null, null, 'Confirm a room before you leave Ranchi.', 'Winter nights on the plateau are colder than in the plains; pack a jacket.', 83),
  ('c2df8324-6e95-5b73-9f64-f2759a93ed04', 'puri/jagannath-entry', 'puri', 'Not everyone can enter the Jagannath Temple', 'Entry to the Jagannath Temple is restricted to Hindus, and phones and leather items aren''t allowed inside. Visitors who can''t enter sometimes view the temple''s exterior from nearby rooftops.', 'local_customs', 'Jagannath Temple', 19.8048, 85.8179, null, null, 'Know the entry rules before you go, and leave your phone at your stay or the deposit counter.', null, 84),
  ('73172347-503e-5faf-9a78-69f40be406f9', 'kolkata/durga-puja-nights', 'kolkata', 'During Durga Puja, the city runs on night time', 'Pandal-hopping during Durga Puja peaks in the evenings and late into the night, and traffic slows to a crawl. Many locals walk or use the Metro rather than cars.', 'planning', 'Kolkata', 22.5726, 88.3639, null, null, 'Plan your pandals by area and move on foot or by Metro.', 'Wear comfortable shoes and agree a meeting point with your group in case you''re separated.', 85),
  ('6166524c-2143-51b1-a5a9-74f5b53a8c9e', 'pelling/morning-views', 'pelling', 'Kanchenjunga is a morning view', 'Clouds usually build up over the range as the day warms. Visitors who arrive in the afternoon and leave after breakfast sometimes miss the peaks completely.', 'weather', 'Pelling', 27.3, 88.237, null, null, 'Be up and looking at first light, and stay two nights if the view matters.', null, 86),
  ('ca416fc0-cf1e-551b-a2a4-d727420a86f6', 'majuli/ferry-timing', 'majuli', 'The ferry decides your arrival time', 'Majuli is reached by ferry from Neamati Ghat near Jorhat. Ferries run a limited schedule and the crossing time changes with the river, so it''s easy to arrive at the ghat just after one has left.', 'transport', 'Neamati Ghat', 26.842, 94.241, null, null, 'Check the day''s ferry times and reach the ghat early.', null, 87),
  ('3704e358-1397-534e-a226-476f35e322d9', 'ziro/festival-stays', 'ziro', 'Festival week fills every homestay', 'When the Ziro Festival of Music is on in autumn, the valley''s homestays and campsites book out. Outside festival dates the valley is quiet and easy to find a room in.', 'planning', 'Ziro festival grounds', 27.55, 93.83, null, null, 'Book months ahead for festival dates, or come another week.', null, 88),
  ('822faf73-ec6e-5dcb-9e02-9601050d55b5', 'dawki/clear-water-season', 'dawki', 'The famous clear water is a winter thing', 'The Umngot''s glass-like water appears in the dry months. During the monsoon the river runs high and muddy, and boating can be suspended.', 'weather', 'Umngot river', 25.188, 92.024, null, null, 'Go between November and April if you want the clear-water views.', null, 89),
  ('e95833dd-731a-551c-afa8-780bc082cfaa', 'imphal/ilp-advisories', 'imphal', 'Check permits and advisories before you go', 'Indian visitors from outside Manipur need an Inner Line Permit. Local conditions have also affected travel in recent years.', 'planning', 'Imphal', 24.817, 93.9368, null, null, 'Apply for the permit before travelling and check current government advisories close to your dates.', null, 90),
  ('4d8e91c1-d01c-505b-8e87-66ecbc78e457', 'aizawl/steep-streets', 'aizawl', 'Aizawl is a city of slopes and stairs', 'Streets climb and drop steeply, and many shortcuts are long flights of steps. Walking a short distance on the map can mean a real climb.', 'accessibility', 'Aizawl', 23.7271, 92.7176, null, null, 'Use local taxis for steep stretches, and ask your stay about step-free access.', null, 91),
  ('449158f9-6b8b-5f48-987d-8c3655b1f365', 'dzukou-valley/steep-start', 'dzukou-valley', 'The climb is front-loaded', 'From the Viswema side, the first part of the trek is a steep climb through forest. Once you reach the ridge, the walk along the valley is much gentler.', 'activity', 'Viswema trailhead', 25.59, 94.1, null, null, 'Start early and pace yourself on the first climb.', null, 92),
  ('75bad001-83d6-5196-b9cc-1086afba1c76', 'agartala/palace-museum', 'agartala', 'The palace is a museum with opening hours', 'Ujjayanta Palace houses the state museum, with set opening hours and a weekly closing day. Arriving late in the afternoon can mean only seeing the gardens.', 'planning', 'Ujjayanta Palace', 23.837, 91.283, null, null, 'Check opening times and visit earlier in the day.', null, 93),
  ('d1dd73f2-0a24-53d8-8b5c-0f247f9b744f', 'swaraj-dweep/ferry-booking', 'swaraj-dweep', 'Book inter-island ferries early', 'Ferries between the capital and Swaraj Dweep fill up in peak season, and sailings can be cancelled in rough weather. A tight connection back to your flight is risky.', 'transport', 'Swaraj Dweep jetty', 12.03, 92.985, null, null, 'Book ferries in advance and leave a buffer day before your flight out.', null, 94),
  ('18d8d932-00c2-5a43-a26f-5836eb6d28d5', 'araku-valley/train-up', 'araku-valley', 'Take the train up and the road down', 'The railway from Visakhapatnam climbs through many tunnels and bridges, and the scenic coaches sell out. The road back allows stops at viewpoints and the Borra Caves.', 'transport', 'Araku railway station', 18.33, 82.873, null, null, 'Book the train well ahead and use the road for the return.', null, 95),
  ('172264a0-8553-5442-af0b-a92c67a8fc78', 'warangal/thousand-pillar', 'warangal', 'The Thousand Pillar Temple is still a temple', 'The Thousand Pillar Temple is an active place of worship as well as a protected monument. Shoes come off, and some areas are for worshippers.', 'local_customs', 'Thousand Pillar Temple', 18.003, 79.575, null, null, 'Dress modestly and follow signs about photography.', null, 96),
  ('bce68530-28b2-5821-9a8a-131a7cb6cbcb', 'hampi/vittala-heat', 'hampi', 'Do Vittala in the morning', 'The stone chariot at the Vittala Temple draws the biggest crowds, and the stone platforms heat up fast. The last stretch is covered by battery vehicles or on foot.', 'weather', 'Vijaya Vittala Temple', 15.343, 76.474, null, null, 'Arrive early, before the crowds and the heat.', null, 97),
  ('5bcfc93c-1670-559c-849a-189f3d7c5d1b', 'kozhikode/sm-street', 'kozhikode', 'SM Street is busiest in the evening', 'Mittai Theruvu, the sweet street, gets very crowded in the evenings and before festivals. It''s a good time for atmosphere but slow for actually buying anything.', 'planning', 'SM Street (Mittai Theruvu)', 11.252, 75.78, null, null, 'Shop in the morning; come back in the evening for the buzz.', null, 98),
  ('f0e3f435-fb76-5d71-9635-b9766c71c0a2', 'madurai/meenakshi-phones', 'madurai', 'Phones stay outside Meenakshi Temple', 'Mobile phones and cameras aren''t allowed inside the Meenakshi temple, and there is a dress code. Visitors who don''t know end up queuing twice.', 'local_customs', 'Meenakshi Amman Temple', 9.9195, 78.1193, null, null, 'Leave your phone at your stay or the deposit counter, and dress modestly.', null, 99),
  ('a8b36b50-578e-5b1b-b546-4083efcecc02', 'old-goa/church-dress', 'old-goa', 'The churches are places of worship', 'The Basilica of Bom Jesus and Se Cathedral are active churches. Beachwear isn''t appropriate, and services may limit where visitors can go.', 'local_customs', 'Basilica of Bom Jesus', 15.5009, 73.9116, null, null, 'Cover shoulders and knees, and avoid service times if you want to look around.', null, 100),
  ('b4a68c4a-5d6c-5e67-97f1-b27849ab6453', 'puducherry/rocky-sea', 'puducherry', 'The town beach isn''t for swimming', 'The seafront in town is lined with rocks and the sea can be rough. For swimming, people head to beaches outside town.', 'safety', 'Rock Beach', 11.932, 79.836, null, null, 'Enjoy the town seafront from the promenade and swim elsewhere.', null, 101),
  ('f2b920d0-1905-53d1-9c86-b6e23917129b', 'sasan-gir/monsoon-closure', 'sasan-gir', 'Gir closes for the monsoon', 'Safaris in Gir National Park stop during the monsoon, roughly from mid-June to mid-October. Permits for the open season are booked online and go early.', 'planning', 'Gir National Park', 21.169, 70.602, null, null, 'Book the official safari permit as soon as your dates are fixed.', 'If you can''t get a permit, the Devalia safari park nearby is a fenced alternative.', 102),
  ('c301179f-9cb6-5885-8fba-8a9f842b5a71', 'mumbai/local-train-peak', 'mumbai', 'Avoid local trains at rush hour with bags', 'Mumbai''s suburban trains are the fastest way across the city, but at peak hours they are packed beyond what most visitors can imagine. Getting on and off with luggage can be impossible.', 'transport', 'Chhatrapati Shivaji Maharaj Terminus', 18.94, 72.8355, null, null, 'Travel off-peak, and take a cab when you''re carrying bags.', 'There are dedicated ladies'' compartments; check the markings on the platform.', 103),
  ('bdf6ba8f-3080-5137-879c-e6833070d487', 'orchha/ram-raja', 'orchha', 'Ram Raja Temple keeps royal hours', 'At the Ram Raja Temple, Rama is worshipped as a king, and the temple opens and closes at set times, closing in the middle of the day. Turning up in the afternoon means a wait.', 'local_customs', 'Ram Raja Temple', 25.351, 78.64, null, null, 'Check darshan timings and plan the palaces around them.', null, 104),
  ('cd53594d-ce47-5543-abe2-1c348a65ad87', 'jagdalpur/bastar-dussehra', 'jagdalpur', 'Bastar Dussehra is a festival of its own', 'Bastar Dussehra is a long festival with unique local rituals, very different from Dussehra elsewhere. The main events draw large crowds to Jagdalpur.', 'planning', 'Danteshwari Temple, Jagdalpur', 19.0756, 82.0219, null, null, 'Check the dates of the key rituals and book ahead if you want to see them.', null, 105),
  ('021eac4e-4f2b-5fbe-abe9-247b34b56d11', 'daman/beach-expectations', 'daman', 'Daman''s beaches are for strolling', 'Daman''s beaches are rocky or muddy in places, with strong tides, so they suit evening walks more than swimming. The old forts are the real highlight.', 'other', 'Devka Beach', 20.43, 72.83, null, null, 'Plan around Moti Daman fort and the promenades, not the sea.', null, 106),
  ('3a0b2950-edbd-5edd-88ae-c15007bd9aad', 'spiti-valley/key-monastery-cash', 'spiti-valley', 'Card machines and ATMs thin out fast up here', 'Small homestays, cafés and taxi drivers around Kaza often prefer cash, and mobile data can drop out for long stretches. A single ATM being empty or offline is enough to change plans.', 'costs', 'Key Monastery', 32.2977, 78.0119, null, null, 'Arrive in Spiti with enough cash for the whole stay.', null, 107),
  ('db5dc6c3-a5b5-55eb-af2f-5e258c13217d', 'anandpur-sahib/hola-mohalla', 'anandpur-sahib', 'Hola Mohalla changes the whole town', 'Around Hola Mohalla, held the day after Holi, the town fills with pilgrims, processions and displays of martial skills. Roads close, rooms disappear and a short visit becomes a long one.', 'planning', 'Takht Sri Kesgarh Sahib', 31.2365, 76.5024, null, null, 'Either plan specifically for the festival or avoid those days.', 'If you go, stay in a nearby town, keep your phone charged and agree on a meeting point with your group.', 108),
  ('f76cec0f-dabe-5b6e-82ae-17e566c7d138', 'kurukshetra/brahma-sarovar-feet', 'kurukshetra', 'The sarovar is bigger and hotter than it looks', 'Walking around Brahma Sarovar means a long loop on open stone, and footwear isn''t allowed near some shrines. On a summer afternoon the paving gets hot enough to hurt.', 'packing', 'Brahma Sarovar', 29.9615, 76.837, null, null, 'Walk the tank in the morning or evening, and carry socks.', null, 109),
  ('61709160-a633-5c06-b9ae-1011edfc0081', 'rishikesh/ganga-current', 'rishikesh', 'Calm-looking water at the ghats still moves fast', 'The river near the ghats looks gentle, but the current is cold and strong, and the bed drops away suddenly. Dipping in is common; swimming out is not a good idea.', 'safety', 'Ram Jhula ghats', 30.1222, 78.3159, null, null, 'Stay where you can stand, hold the chains where provided, and keep children close.', null, 110),
  ('1a0884ad-fdd3-55d1-a645-98931172cf9f', 'varanasi/dawn-boat', 'varanasi', 'The river is best before breakfast', 'By mid-morning the ghats are hot and busy. At dawn the light is soft, people are bathing and praying, and a slow boat along the river shows the city''s whole length.', 'activity', 'Dashashwamedh Ghat', 25.3069, 83.0105, null, null, 'Book the boat the evening before and agree the route and duration up front.', null, 111),
  ('96d9c97a-0286-513e-955a-f6c419a714a2', 'jaisalmer/desert-night-cold', 'jaisalmer', 'Desert nights in winter are properly cold', 'Winter days in the Thar are pleasant, so it''s tempting to pack light. After sunset on the dunes the temperature drops sharply, and a desert camp can feel very cold by midnight.', 'packing', 'Sam sand dunes', 26.832, 70.514, null, null, 'Carry a warm layer and a cap for a dune night in winter.', null, 112),
  ('a14cc6d4-0691-549a-866c-b978b9496f75', 'pahalgam/pony-terms', 'pahalgam', 'Be clear about which meadows a pony ride includes', 'Pony rides to the meadows around Pahalgam are often sold as packages of several viewpoints. Misunderstandings usually come from which points are included and how long you get at each.', 'costs', 'Baisaran meadow trail', 34, 75.33, null, null, 'Write down the list of stops and the total time before you start.', 'Check current local advisories for the meadows before you go.', 113),
  ('1645b10b-0c07-5f3b-b5ff-37c27106756d', 'bodh-gaya/winter-pilgrims', 'bodh-gaya', 'Winter is pilgrim season', 'The cooler months bring monks and pilgrims from across Asia, along with teachings and ceremonies. It''s a moving time to visit, but rooms near the temple fill early.', 'planning', 'Bodh Gaya', 24.6961, 84.987, null, null, 'Book ahead for December and January, or stay a little further out.', null, 114),
  ('57ca321c-81c7-59db-a6ba-a95ae4d9ba3a', 'ranchi/hundru-steps', 'ranchi', 'Hundru Falls is a lot of steps down', 'Reaching the pool at the base of Hundru means hundreds of steps down and the same back up. In the monsoon the steps are wet and the water is powerful.', 'activity', 'Hundru Falls', 23.451, 85.651, null, null, 'Pace yourself on the way down; the climb back is the hard part.', null, 115),
  ('fe63498d-cf04-5b4d-ba30-fce25122535d', 'puri/beach-currents', 'puri', 'Puri''s waves are stronger than they look', 'The sea at Puri has strong waves and currents, and conditions change with the season. Lifeguards patrol parts of the beach and use flags to show where bathing is risky.', 'safety', 'Puri beach', 19.7983, 85.8249, null, null, 'Bathe only near lifeguards and follow their flags.', null, 116),
  ('46eaaf72-6982-5c1d-a9e7-b0a83f35b9e6', 'kolkata/museum-days', 'kolkata', 'Check weekly closing days before you plan the day', 'Several of Kolkata''s museums and galleries have a weekly closing day, and Monday is a common one. A day built around the Victoria Memorial galleries can shrink to a walk in the gardens.', 'planning', 'Victoria Memorial', 22.5448, 88.3426, null, null, 'Look up each museum''s closing day before arranging your Kolkata itinerary.', null, 117),
  ('124d57d6-c6a1-5aed-9946-c527c9bfba03', 'lachung/north-sikkim-permits', 'lachung', 'North Sikkim runs on permits and packages', 'Travel to Lachung and Yumthang requires permits arranged through registered operators, and most trips are sold as packages from Gangtok. Independent plans built on the spot rarely work.', 'planning', 'Lachung', 27.689, 88.743, null, null, 'Arrange the trip through a registered operator with your documents in hand.', null, 118),
  ('07fe7dbf-741c-50dc-b34a-b4a43ccb7e11', 'majuli/satra-respect', 'majuli', 'Satras are living monasteries', 'The satras of Majuli are active religious communities, not museums. Monks live, pray and perform there, and some areas are off-limits to visitors.', 'local_customs', 'Auniati Satra', 26.95, 94.17, null, null, 'Ask before entering prayer halls or taking photos, and dress modestly.', null, 119),
  ('b011ac4a-cb2e-5ef9-9ebd-449df9a3f9c2', 'ziro/village-etiquette', 'ziro', 'Apatani villages are homes, not exhibits', 'Visitors walk through Apatani villages to see traditional houses and fields. Photographing people, especially elders, without asking is unwelcome.', 'local_customs', 'Hong village', 27.56, 93.84, null, null, 'Visit with a local guide and always ask before taking photos.', null, 120),
  ('c9210b28-8ec5-5812-90d1-c7aad2b078b5', 'mawlynnong/village-rules', 'mawlynnong', 'Respect the village''s rules', 'Mawlynnong takes pride in its cleanliness, and visitors are expected to follow its rules on littering and where to go. It''s a small, lived-in village, so day-trip crowds can overwhelm it.', 'local_customs', 'Mawlynnong', 25.201, 91.916, null, null, 'Use the bins, keep to paths, and visit early or on a weekday.', null, 121),
  ('641c80ab-9ed1-5fc5-afb0-e2afb34c3485', 'imphal/ima-keithel', 'imphal', 'Ima Keithel is a market run by women', 'Ima Keithel, the mothers'' market, is a large market where only women hold stalls. It''s a working market, and stallholders are busy trading.', 'local_customs', 'Ima Keithel', 24.809, 93.938, null, null, 'Buy something rather than only photographing, and ask before taking pictures of people.', null, 122),
  ('a63b41fa-94f0-5320-ae7b-067e3ab394de', 'reiek/clear-morning', 'reiek', 'Reiek is about the view, so go when it''s clear', 'The point of Reiek is the long view over ridges and valleys. On a misty day, you''ll mainly see cloud.', 'weather', 'Reiek Tlang', 23.703, 92.597, null, null, 'Go on a clear morning in the dry season.', null, 123),
  ('cb5ec21a-ff8a-5a20-b95a-3c307f8a340c', 'dzukou-valley/carry-out', 'dzukou-valley', 'Pack everything for the night', 'Facilities in the valley are basic, and nights get cold. Supplies have to be carried up, and so does the rubbish on the way back down.', 'packing', 'Dzukou rest house', 25.558, 94.079, null, null, 'Bring warm layers, a torch, food and a bag for your waste.', null, 124),
  ('1740664a-8d41-5917-98e2-2d959144c0fe', 'neermahal/lake-levels', 'neermahal', 'The water palace depends on the water', 'Neermahal is reached by boat across Rudrasagar Lake, and the lake level changes through the year. In drier months the palace looks less like it''s floating.', 'weather', 'Rudrasagar Lake', 23.513, 91.32, null, null, 'Visit after the monsoon for the fullest lake.', null, 125),
  ('02d5da89-1a86-56f5-a2fa-95b3aab87d36', 'swaraj-dweep/dive-flight', 'swaraj-dweep', 'Don''t fly right after diving', 'Dive operators recommend a gap between diving and flying to reduce the risk of decompression sickness. A dive on your last morning can clash with an afternoon flight.', 'safety', 'Radhanagar Beach', 11.984, 92.952, null, null, 'Plan dives early in the trip and follow your operator''s no-fly guidance.', null, 126),
  ('01f830c8-d0d7-5974-b2be-0942d2feff45', 'araku-valley/borra-caves', 'araku-valley', 'Borra Caves are damp and slippery inside', 'The limestone caves at Borra are large, humid and wet underfoot in places, with steps going down into the chamber.', 'activity', 'Borra Caves', 18.28, 83.039, null, null, 'Wear shoes with grip, not sandals.', null, 127),
  ('93b1b777-cb05-5086-a143-156ac650aebf', 'hyderabad/golconda-evening', 'hyderabad', 'Golconda is best late in the day', 'Climbing Golconda Fort in the midday heat is hard work. Late afternoon is cooler, and the evening sound and light show is right there.', 'planning', 'Golconda Fort', 17.3833, 78.4011, null, null, 'Arrive mid-afternoon, climb, then stay for the show.', null, 128),
  ('fd98c517-9034-5a86-98ae-2e4f263e9934', 'mysuru/palace-lights', 'mysuru', 'The palace lights up only on certain evenings', 'Mysuru Palace is illuminated on Sunday evenings, public holidays and during Dasara, not every night. Visitors who come on an ordinary weekday evening find it dark.', 'planning', 'Mysuru Palace', 12.3052, 76.6552, null, null, 'Plan your Mysuru evening around the illumination schedule.', null, 129),
  ('90c324a6-5198-59d2-89ef-98742c1df931', 'kozhikode/beach-sunset', 'kozhikode', 'The beach is for walking, not swimming', 'Kozhikode Beach is a promenade where families come for sunset and snacks. The sea here isn''t really for swimming, especially in the monsoon.', 'activity', 'Kozhikode Beach', 11.256, 75.77, null, null, 'Come for the evening walk and food stalls.', null, 130),
  ('be201bed-7ae9-5351-915d-5c00289c17e4', 'mahabalipuram/spread-monuments', 'mahabalipuram', 'The monuments are spread around town', 'The Shore Temple, Arjuna''s Penance and the Five Rathas are in different parts of town, with open ground and little shade in between.', 'planning', 'Shore Temple', 12.6165, 80.199, null, null, 'Start early, and consider a bicycle or auto between sites.', null, 131),
  ('e9b5ccd5-79e1-5c5b-a4fa-dc6406cd2790', 'dudhsagar/jeep-season', 'dudhsagar', 'The jeep trips pause in the monsoon', 'The usual way to the falls is a forest jeep from Collem, and these trips stop during the monsoon, exactly when the falls are fullest. Walking along the railway line is unsafe and prohibited.', 'planning', 'Collem jeep stand', 15.346, 74.249, null, null, 'Visit just after the monsoon, when the jeeps resume and the falls are still strong.', null, 132),
  ('c4175633-f85a-51da-a3da-b80156116ace', 'ahmedabad/heritage-walk', 'ahmedabad', 'See the pols on foot in the early morning', 'The old city''s pols are dense neighbourhoods of carved wooden houses and lanes too narrow for cars. Morning heritage walks start early to beat the heat and the traffic.', 'activity', 'Old city pols', 23.026, 72.59, null, null, 'Join a guided morning walk rather than driving through.', null, 133),
  ('a57736e5-49f0-57e2-9e32-a85e2a7ae4e3', 'mumbai/monsoon-flooding', 'mumbai', 'Monsoon downpours can stop the city', 'Heavy monsoon rain sometimes floods low-lying roads and stops trains for hours. Flights and airport transfers are affected too.', 'weather', 'Mumbai', 19.076, 72.8777, null, null, 'Leave long buffers for airport and station transfers in the monsoon.', null, 134),
  ('a8bb7705-46c2-5365-8d3c-bf59914be665', 'pachmarhi/gypsy-permits', 'pachmarhi', 'Many viewpoints are reached by gypsy, with a permit', 'Several of Pachmarhi''s sights lie inside the Satpura Tiger Reserve, and private cars aren''t allowed on some routes. Visitors take registered open jeeps with entry permits.', 'transport', 'Dhoopgarh', 22.46, 78.379, null, null, 'Arrange a registered gypsy and permit from the town counter.', null, 135),
  ('b4296f06-b090-54b4-b3d4-c0604f568328', 'jagdalpur/kanger-valley', 'jagdalpur', 'Kanger Valley sites close in the monsoon', 'Some attractions in Kanger Valley National Park, such as the caves, close during the monsoon. The waterfalls are full then, but you won''t see everything.', 'planning', 'Kanger Valley National Park', 18.87, 81.95, null, null, 'Check which sites are open before planning a day in the park.', null, 136),
  ('75fcd4f5-f4ce-5530-a7d8-66a98df10a43', 'mcleod-ganj/triund-weekend', 'mcleod-ganj', 'Triund on a Saturday is a different trek', 'The Triund trail is short enough for a day hike, so it fills up on weekends and holidays. The ridge-top can feel more like a fair than a mountain.', 'activity', 'Triund trail', 32.26, 76.348, null, null, 'Pick a weekday, or start at first light.', 'Carry your rubbish back down; there is no one to collect it for you at the top.', 137),
  ('b72bdd78-5c05-5a14-a27f-3edc4f036393', 'patiala/old-city-parking', 'patiala', 'Don''t drive into the old bazaars', 'The lanes around Qila Mubarak are narrow and packed with shoppers and two-wheelers. Getting a car in is easy; getting it out again is the hard part.', 'transport', 'Qila Mubarak area', 30.3302, 76.4027, null, null, 'Park outside the old quarter and walk or take a rickshaw in.', null, 138),
  ('008dc38e-42c7-546a-a520-4f6af3e3541b', 'pinjore/gardens-evening', 'pinjore', 'The gardens are a stop, not a detour', 'Pinjore''s Mughal-style terraced gardens sit right on the way to the hills, which makes them an easy break on the drive. The fountains and lights are the draw in the evening, so the order of your day matters.', 'planning', 'Yadavindra Gardens', 30.7948, 76.9139, null, null, 'Plan the stop for late afternoon on the way back rather than first thing on the way up.', null, 139),
  ('25803a5e-19b7-5e08-b5c5-c94787ad6b66', 'rishikesh/town-rules', 'rishikesh', 'Rishikesh keeps a vegetarian, quiet centre', 'Meat and alcohol are not served in the central pilgrimage areas. If you''re expecting a beach-town evening by the river, you''ll find chai and kirtan instead.', 'local_customs', 'Laxman Jhula area', 30.1272, 78.3297, null, null, 'Read the town for what it is and plan your evenings accordingly.', null, 140),
  ('657834ea-e4f8-550f-84f4-e2e7438847fa', 'varanasi/lane-navigation', 'varanasi', 'Maps give up in the old lanes', 'The galis behind the ghats are narrow, twisting and often unnamed on maps. Cars can''t get in, so drivers drop you at the edge and you walk the rest with your bags.', 'transport', 'Old city lanes', 25.31, 83.008, null, 'Finding a stay in the lanes after dark can take a while.', 'Ask your stay for a landmark and a phone number, and arrive in daylight if you can.', null, 141),
  ('5bc9d48e-d4df-5d9e-9017-d704cd917cec', 'jaisalmer/living-fort', 'jaisalmer', 'People live inside the fort', 'Jaisalmer Fort is still lived in, with homes, temples and shops inside its walls. The narrow lanes are someone''s front step, and doorways aren''t backdrops.', 'local_customs', 'Jaisalmer Fort', 26.9124, 70.9126, null, null, 'Ask before photographing people or homes, and keep the noise down in the lanes.', null, 142),
  ('1727e136-311f-59e8-8bbc-2e8f3664bf8c', 'rajgir/ropeway-queue', 'rajgir', 'The ropeway queue sets the pace of the day', 'The ropeway up to the Peace Pagoda on Ratnagiri hill is popular with day-trippers and pilgrims. On holidays, the wait at the bottom can be longer than the ride.', 'planning', 'Vishwa Shanti Stupa ropeway', 25.011, 85.433, null, null, 'Do the ropeway first thing, then Nalanda later in the day.', null, 143),
  ('b08b478c-d5a8-52ee-8cb6-8f07b28c79b4', 'ranchi/falls-swimming', 'ranchi', 'Waterfall pools are not swimming pools', 'The pools below the falls around Ranchi have strong currents and slippery rocks, especially after rain. Warning signs are there for a reason.', 'safety', 'Dassam Falls', 23.144, 85.466, null, null, 'Stay out of the water where swimming is prohibited, and stay off wet rocks near the edge.', null, 144),
  ('0161becf-2c80-5910-9e5e-e8acd8cc2f72', 'konark/guide-carvings', 'konark', 'The wheels make more sense with a guide', 'The Sun Temple''s carved wheels and walls are full of detail that''s easy to walk past. A licensed guide can point out how the wheels work as sundials and what the friezes show.', 'activity', 'Konark Sun Temple', 19.8876, 86.0945, null, null, 'Hire an approved guide at the site, and agree the length of the tour first.', null, 145),
  ('716f241e-0ded-569c-8214-21c74ac93e6c', 'sundarbans/boat-days', 'sundarbans', 'It''s mostly a boat trip, and that''s the point', 'Visits to the Sundarbans are spent largely on boats through channels and creeks, with short stops at watchtowers. Tiger sightings are rare, and tides shape the day.', 'activity', 'Sajnekhali', 22.121, 88.827, null, null, 'Go for the mangroves, birds and river life; a tiger would be extraordinary luck.', 'Stay on the boat unless at an authorised stop, and use operators who handle forest permits.', 146),
  ('f9cdb1e2-a25b-5115-a6af-7f6f8068dac2', 'lachung/landslide-season', 'lachung', 'Monsoon roads can close without warning', 'Roads into North Sikkim are prone to landslides in the monsoon, and access has been restricted for long periods after floods. Tours can be cancelled the night before.', 'weather', 'Yumthang Valley', 27.826, 88.696, null, null, 'Check current road status and keep flexible dates for North Sikkim.', null, 147),
  ('e503bc6c-f4c3-5390-b3f8-293c272ee97d', 'guwahati/kamakhya-ambubachi', 'guwahati', 'Kamakhya closes for a few days around Ambubachi', 'During the Ambubachi Mela in June, the Kamakhya temple''s doors close for several days and the hill fills with pilgrims. At other times the darshan queue can still be long.', 'planning', 'Kamakhya Temple', 26.1663, 91.7055, null, null, 'Check the temple calendar before planning a visit around darshan.', null, 148),
  ('2a04adc3-c516-5a7b-a9bb-edc3a1b9299c', 'dirang/break-journey', 'dirang', 'Dirang is the right place to break the drive', 'The drive from the plains to Tawang is long and climbs steeply. Stopping overnight in Dirang breaks it up and helps you adjust before the higher pass.', 'transport', 'Dirang', 27.358, 92.24, null, null, 'Plan a night in Dirang on the way up.', null, 149),
  ('7cba3934-6dd3-51ec-8ff4-3ff4d1c67dd6', 'shillong/traffic', 'shillong', 'Shillong''s traffic can eat your afternoon', 'Narrow roads and heavy traffic around central Shillong slow everything down, especially at school and office hours. A short trip across town can take a surprising amount of time.', 'transport', 'Police Bazar', 25.5745, 91.8826, null, null, 'Leave for the airport or outlying sights with a generous buffer.', null, 150),
  ('74839862-ade6-5846-9e0c-f94a04beb20b', 'ukhrul/shirui-lily', 'ukhrul', 'The Shirui lily blooms only briefly', 'The rare Shirui lily blooms on the slopes of Shirui Kashung around the start of the monsoon. Outside that window you''ll see grassy hills but no lilies.', 'weather', 'Shirui Kashung', 25.104, 94.428, null, null, 'Time the trip for the bloom, and stay on paths; picking the flower isn''t allowed.', null, 151),
  ('b091a4ae-f35a-57bc-8674-c3be11da5e9f', 'champhai/long-drive', 'champhai', 'Champhai is a full day from Aizawl', 'The road from Aizawl to Champhai is long and winding. Shared sumos run in the morning, and travelling after dark isn''t practical.', 'transport', 'Champhai', 23.472, 93.326, null, null, 'Leave early and plan to stay at least two nights.', null, 152),
  ('c406a410-4d0b-5d8a-b231-0a6ec2448971', 'khonoma/guided-walk', 'khonoma', 'A village guide makes Khonoma make sense', 'Khonoma''s history, morungs and conservation story aren''t obvious from a quick walk-through. Local guides can explain the village and its customs.', 'local_customs', 'Khonoma', 25.653, 94.022, null, null, 'Arrange a guide through the village and follow their lead on where to go.', null, 153),
  ('8b83db52-9572-5b0c-82c2-6881c83b5f7a', 'udaipur-tripura/two-udaipurs', 'udaipur-tripura', 'Make sure you''re booking the right Udaipur', 'Udaipur in Tripura shares its name with the much better-known city in Rajasthan. Booking sites and maps sometimes default to the Rajasthan one.', 'planning', 'Tripura Sundari Temple', 23.515, 91.498, null, null, 'Double-check the state on every booking and map search.', null, 154),
  ('696c1602-2e02-5cd9-8b3a-a909ee8e6b15', 'tirupati/darshan-booking', 'tirupati', 'Book darshan before you arrive', 'Darshan at Tirumala is managed through tickets and time slots, many of which are booked online well in advance. Without a slot, the free queue can take many hours.', 'planning', 'Tirumala', 13.6833, 79.3474, null, null, 'Book through the official temple website, and check the dress code for your darshan type.', null, 155),
  ('002ef4ce-c9ed-5d22-b7e6-c82100bda89f', 'hyderabad/charminar-crowds', 'hyderabad', 'The old city is busiest in the evenings', 'The bazaars around Charminar get very crowded in the evenings and during festivals, especially Ramzan nights. It''s lively, but driving is close to impossible.', 'planning', 'Charminar', 17.3616, 78.4747, null, null, 'Go on foot, keep valuables close and accept the slow pace.', null, 156),
  ('21a8c0ed-9d62-58c0-8e37-df4ce024f78a', 'madikeri/monsoon-leeches', 'madikeri', 'Leeches come with the green', 'Coorg in the monsoon is lush and wet, and leeches are common on forest and estate trails. They''re harmless but unpleasant if you''re not expecting them.', 'packing', 'Abbey Falls', 12.456, 75.718, null, null, 'Wear closed shoes and leech socks on monsoon walks.', null, 157),
  ('42cdeb11-1bca-56b4-85e9-e95aa06c01f1', 'alappuzha/houseboat-hours', 'alappuzha', 'Read what an overnight houseboat actually includes', 'Overnight houseboats don''t cruise all night; they moor in the evening and the time actually moving can be shorter than people expect. Check-in and check-out times shape the trip too.', 'planning', 'Alappuzha houseboat terminal', 9.505, 76.345, null, null, 'Ask for the cruising hours, route and what''s included in writing before you pay.', null, 158),
  ('c229ff9b-6fb4-53a9-9f35-4d5395364792', 'rameswaram/dhanushkodi-wind', 'rameswaram', 'Dhanushkodi is wind, sand and sun', 'The road to Dhanushkodi runs along a narrow strip of sand between two seas, with almost no shade. It''s often very windy.', 'packing', 'Dhanushkodi', 9.152, 79.444, null, null, 'Carry water, sunglasses and something to cover your head.', null, 159),
  ('fe8cb946-a331-5e5c-acbc-65650c01a50b', 'panaji/scooter-licence', 'panaji', 'Rented scooters still need a licence and helmet', 'Renting a scooter is easy in Goa, but traffic police check licences and helmets. Riding without them can mean a fine and a ruined afternoon.', 'transport', 'Fontainhas', 15.497, 73.833, null, null, 'Carry your driving licence and wear a helmet.', null, 160),
  ('641e4108-c5fc-5316-b454-2992ab8f8a39', 'ekta-nagar/monday', 'ekta-nagar', 'The Statue of Unity is closed on Mondays', 'The statue and its viewing gallery are closed on Mondays for maintenance, and gallery tickets are sold in time slots that fill up on weekends.', 'planning', 'Statue of Unity', 21.838, 73.7191, null, null, 'Avoid Mondays and book the viewing gallery slot online.', null, 161),
  ('c5e8d66f-ea92-55bb-83bf-52008a21ee70', 'malvan/water-sports-season', 'malvan', 'Snorkelling and boats stop in the monsoon', 'Boats to Sindhudurg Fort and water sports along the Konkan coast stop during the monsoon, when the sea is rough. The coast is still green and beautiful then, just not for the sea.', 'activity', 'Sindhudurg Fort', 16.044, 73.462, null, null, 'Plan sea activities between October and May.', null, 162),
  ('fbeec4ec-4f3f-5043-b500-f422c1e2fbe9', 'kanha/core-closure', 'kanha', 'Core zones close in the monsoon', 'The core zones of Madhya Pradesh''s tiger reserves close during the monsoon, usually from July to the end of September. Safari permits for the open season sell out months ahead.', 'planning', 'Kanha (Mukki gate)', 22.25, 80.63, null, null, 'Book permits through the official portal as soon as booking opens.', null, 163),
  ('baa1d2cb-610b-5fd1-b7e6-8625a45c4344', 'mainpat/cold-nights', 'mainpat', 'Mainpat is colder than the rest of Chhattisgarh', 'Mainpat sits on a high plateau, and winter nights are much colder than in the plains around it.', 'packing', 'Mainpat', 22.82, 83.28, null, null, 'Pack warm clothes for a winter trip, even if Raipur felt mild.', null, 164),
  ('83a19964-ea67-5a24-8fd7-9658b6abd359', 'mcleod-ganj/tsuglagkhang-kora', 'mcleod-ganj', 'Walk clockwise around the temple', 'Around Tibetan Buddhist temples and stupas, people walk the circuit clockwise. Going the other way doesn''t get you shouted at, but you''ll be swimming against everyone, prayer wheels included.', 'local_customs', 'Tsuglagkhang complex', 32.2327, 76.3243, null, null, 'Follow the flow of the kora and keep to the left of shrines.', 'Look for signs about photography inside the main temple before taking out your phone.', 165),
  ('a374333b-6675-5367-ae01-2074237b655d', 'pithoragarh/munsiyari-distance', 'pithoragarh', 'Munsiyari is close on the map and far on the road', 'The drive from Pithoragarh to Munsiyari winds through river valleys and over ridges, and it eats most of a day. Shared jeeps usually leave in the morning and don''t run late.', 'transport', 'Road to Munsiyari', 29.85, 80.25, null, null, 'Treat the transfer as a full travel day.', 'Ask at the jeep stand the evening before about departure times.', 166),
  ('c252115f-7fb0-5399-8fab-4140798a325f', 'lucknow/bara-imambara', 'lucknow', 'The maze at Bara Imambara is easier with a guide', 'The Bhool Bhulaiya inside Bara Imambara is a real labyrinth of narrow passages and staircases. Going in alone is part of the fun until it isn''t.', 'activity', 'Bara Imambara', 26.8692, 80.9128, null, null, 'Take an authorised guide from the ticket counter for the maze.', 'Dress modestly; the complex includes a mosque.', 167),
  ('685a85c4-8487-584b-81c4-a7d4f7c6c00d', 'udaipur/lake-levels', 'udaipur', 'The lakes depend on the monsoon', 'How full Pichola and Fateh Sagar look depends on the previous monsoon. After a weak year, boat routes can be shorter and some ghats sit well above the water.', 'weather', 'Lake Pichola', 24.5724, 73.6797, null, null, 'Don''t build a trip only around lake photos from a good year.', null, 168),
  ('4f4c1531-20f9-5659-b592-11296164b4d0', 'vaishali/spread-out', 'vaishali', 'Arrange transport for the whole circuit', 'Vaishali''s sites are spread across fields and villages, and local transport between them is limited. Visitors relying on finding autos on the spot can end up waiting on empty roads.', 'transport', 'Kolhua Ashokan pillar', 25.999, 85.134, null, null, 'Hire a car or auto for the full visit from Patna or Hajipur.', null, 169),
  ('067cc85a-bfd4-5d81-8bcc-722eb64f0aa2', 'betla-national-park/safari-expectations', 'betla-national-park', 'Go for the forest, not just a tiger', 'Sightings in a forest reserve are never guaranteed. Visitors who come only for big cats can leave disappointed, while those who enjoy the sal forest, birds and the Palamau forts usually leave happy.', 'activity', 'Betla safari gate', 23.887, 84.191, null, null, 'Set your expectations around the landscape.', 'Morning drives tend to be cooler and quieter.', 170),
  ('36a389c0-9f02-50d7-a58c-04f5798610b9', 'chilika-lake/dolphin-boats', 'chilika-lake', 'Dolphins aren''t on a schedule', 'Boats from Satapada head out to where Irrawaddy dolphins are often seen, but sightings are brief and distant. Boats chasing the animals don''t improve the odds.', 'activity', 'Satapada jetty', 19.668, 85.444, null, null, 'Go for the lagoon and treat any dolphin sighting as a bonus.', 'Ask whether the boat trip includes a long stop at the sea-mouth and shops; it adds time.', 171),
  ('8574ca4d-dc6b-547f-a188-09ecadbff664', 'shantiniketan/wednesday-holiday', 'shantiniketan', 'The campus keeps its own weekly holiday', 'Visva-Bharati traditionally takes its weekly holiday on Wednesday rather than Sunday. Museums and parts of the campus may be closed that day.', 'planning', 'Visva-Bharati campus', 23.6797, 87.6838, null, null, 'Check opening days for Rabindra Bhavana and the campus before you fix your visit.', null, 172),
  ('df0f7d03-4617-5933-b28f-feec6ed6f945', 'sivasagar/ahom-circuit', 'sivasagar', 'The Ahom monuments are spread out', 'Sivasagar''s monuments sit across town and the surrounding countryside. Without your own transport, it''s hard to string them together in one day.', 'transport', 'Rang Ghar', 26.975, 94.625, null, null, 'Hire an auto or car for the day.', null, 173),
  ('eaecdc68-9585-529d-baaf-ddcca0e8ea66', 'lepakshi/ceilings', 'lepakshi', 'Look up', 'Most visitors head straight for the famous hanging pillar. The painted ceilings of the temple''s halls are just as remarkable and easy to miss.', 'activity', 'Veerabhadra Temple', 13.8016, 77.6094, null, null, 'Slow down inside the temple, or ask a guide to point out the murals.', null, 174),
  ('ad0dbb86-def9-50fd-b7f8-add4c8f17ac2', 'ananthagiri-hills/monsoon-fog', 'ananthagiri-hills', 'Monsoon weekends bring fog and crowds', 'In the monsoon the hills are green and misty, and so is the road. Weekend traffic from Hyderabad adds to slow, low-visibility driving.', 'weather', 'Ananthagiri Hills', 17.31, 77.86, null, null, 'Go on a weekday and drive carefully in the fog.', null, 175),
  ('5bb390dd-43d9-5bf3-89f2-23c580853ee7', 'gokarna/beach-trek', 'gokarna', 'The beach trek has rocky, shadeless stretches', 'The coastal walk between Kudle, Om, Half Moon and Paradise beaches crosses headlands with rocky sections and little shade. Some stretches are tricky in the dark.', 'activity', 'Om Beach', 14.52, 74.324, null, null, 'Start in the morning, carry water and turn back with daylight to spare.', null, 176),
  ('111b9f62-83fb-5193-9e12-250dabe10889', 'alappuzha/boat-race', 'alappuzha', 'Race day changes everything on the water', 'On the day of the Nehru Trophy Boat Race in August, Punnamada Lake fills with spectators and houseboat traffic is restricted. It''s a spectacle, but not a quiet backwater day.', 'planning', 'Punnamada Lake', 9.52, 76.345, null, null, 'Book race tickets ahead, or choose a different day for a calm cruise.', null, 177),
  ('8ccaeaa1-db76-5238-868b-5ce9df7a46c3', 'kodaikanal/plastic-rules', 'kodaikanal', 'Kodaikanal is strict about plastic', 'Single-use plastics such as bottles and bags are restricted in Kodaikanal, and checks can happen at the entry. Visitors carrying cases of bottled water sometimes have to leave them behind.', 'local_customs', 'Kodaikanal Lake', 10.234, 77.488, null, null, 'Bring a reusable bottle and cloth bags.', null, 178),
  ('67726508-e388-5ba2-af59-d0d243133139', 'dholavira/remote-site', 'dholavira', 'Dholavira is remote, so plan the day around it', 'Dholavira sits far out on Khadir Bet, with a long drive from Bhuj and few services on the way. There''s little shade on the site.', 'planning', 'Dholavira archaeological site', 23.887, 70.213, null, null, 'Fuel up, carry water and food, and start early from Bhuj.', null, 179),
  ('027e4ecf-434f-5386-8966-b750dcdc318f', 'ganpatipule/konkan-railway', 'ganpatipule', 'Konkan Railway runs slower in the monsoon', 'The Konkan Railway uses a separate, slower monsoon timetable to manage risk on its cuttings and bridges. Trains take longer and arrive at different times than in the dry season.', 'transport', 'Ratnagiri station', 16.99, 73.31, null, null, 'Check the monsoon timetable for your dates before planning connections.', null, 180),
  ('812b62df-f187-560a-b8f6-63232755251d', 'sanchi/gateway-carvings', 'sanchi', 'The gateways are the point, so go slowly', 'The Great Stupa looks simple from afar, but its four gateways are covered in carved stories. A short visit from Bhopal often skims past them.', 'activity', 'Great Stupa', 23.4795, 77.7399, null, null, 'Spend time at each gateway, and visit the site museum first.', null, 181),
  ('84f72495-f663-5a3d-a0b1-2abf877b96d3', 'sirpur/site-spread', 'sirpur', 'Sirpur''s sites are spread along the river', 'Sirpur''s excavated monasteries and temples are scattered around the village, with modest signage. It''s easy to see the Laxman Temple and miss the rest.', 'planning', 'Laxman Temple, Sirpur', 21.348, 82.181, null, null, 'Hire a local guide and allow at least half a day.', null, 182),
  ('b2058495-cb05-5e79-ad89-f32506c3a009', 'shimla/toy-train-seats', 'shimla', 'The toy train is a ride, not a shortcut', 'The narrow-gauge line from Kalka is slow and lovely, and in season the seats go well before the travel date. Treat it as part of the holiday rather than the fast way up.', 'transport', 'Shimla railway station', 31.103, 77.155, null, 'Turning up hoping for a same-day seat in peak season rarely works.', 'Book the train early, or take the road up and the train for a shorter section.', null, 183),
  ('588f3aae-2d54-555d-933a-13ec94d3e560', 'pithoragarh/munsiyari-views', 'pithoragarh', 'The Panchachuli peaks show up in the morning', 'Clouds tend to build over the mountains as the day goes on. Arriving in the afternoon and leaving next morning can mean barely seeing the peaks that make Munsiyari famous.', 'weather', 'Munsiyari', 30.067, 80.238, null, null, 'Stay at least two nights so you get two dawns.', null, 184),
  ('430ad100-1ab3-5937-b53d-39d00fc1faba', 'prayagraj/sangam-boats', 'prayagraj', 'Agree the boat ride before you step in', 'Boats to the Sangam leave from several ghats, and the price depends on the boat, the season and how many people share it. Confusion usually starts when nothing was agreed before setting off.', 'costs', 'Triveni Sangam', 25.425, 81.885, null, null, 'Settle the fare, the route and whether it''s shared before boarding.', null, 185),
  ('c47d195e-777e-5bad-826b-70f63f2c79cf', 'pushkar/fair-crowds', 'pushkar', 'The camel fair takes over the whole town', 'The fair, held around the Kartik full moon in autumn, brings traders, pilgrims and photographers in large numbers. Rooms book out early and prices rise across town.', 'planning', 'Pushkar fair ground', 26.4926, 74.5432, null, null, 'Book well ahead for fair dates, or visit outside them for a quieter Pushkar.', 'Pushkar is a vegetarian town; meat, eggs and alcohol aren''t served in the centre.', 186),
  ('c3799c80-cb32-536c-874f-36e9915bbef9', 'chilika-lake/mangalajodi-winter', 'chilika-lake', 'Bird season at Mangalajodi is winter', 'The wetlands at Mangalajodi fill with migratory birds in the cooler months. A summer visit shows a much quieter marsh.', 'weather', 'Mangalajodi', 19.888, 85.452, null, null, 'Plan birding trips between late autumn and early spring, and go at dawn.', null, 187),
  ('254e4e79-7e94-54c7-b625-545447209487', 'badami/caves-monkeys', 'badami', 'Keep food away from the cave monkeys', 'The steps up to the cave temples are home to a lot of monkeys that are used to snatching food and loose items.', 'safety', 'Badami cave temples', 15.918, 75.685, null, null, 'Keep food out of sight and bags closed.', null, 188),
  ('80f96421-61c3-5a24-a48d-885d8cfbedd8', 'fort-kochi/friday-closures', 'fort-kochi', 'Fridays are a quiet day in Mattancherry', 'Mattancherry Palace and the Paradesi Synagogue both have weekly closures that include Friday. A heritage walk planned for that day can miss both.', 'planning', 'Mattancherry Palace', 9.958, 76.259, null, null, 'Visit Mattancherry earlier in the week.', null, 189),
  ('e4f0f5a3-1b7b-5399-b07c-1c06f558aa27', 'karaikudi/mansions-private', 'karaikudi', 'Most mansions are private homes', 'Many of Chettinad''s grand mansions are still family homes. Only some are open to visitors, often for a fee, and walking into a courtyard uninvited isn''t welcome.', 'local_customs', 'Kanadukathan', 10.17, 78.78, null, null, 'Visit the mansions that are open, or go with a local guide who arranges access.', null, 190),
  ('039d7142-f38e-58ab-93ea-caa24b073df5', 'ganpatipule/sea-currents', 'ganpatipule', 'The beach is gentle-looking but has currents', 'Ganpatipule''s beach looks calm, but strong currents have caught swimmers here. Lifeguards and flags mark safer areas.', 'safety', 'Ganpatipule beach', 17.144, 73.266, null, null, 'Swim only where it''s marked safe, and not at all in rough weather.', null, 191),
  ('ad3a2a83-e272-5b38-bba2-a6511891c029', 'mandu/monsoon-mandu', 'mandu', 'Mandu is at its best in the rains', 'The monuments of Mandu sit among lakes that fill in the monsoon, when the plateau turns green. In summer, the same sites are dry and hot.', 'weather', 'Jahaz Mahal', 22.354, 75.39, null, null, 'Visit during or just after the monsoon, and keep a full day for the spread-out sites.', null, 192),
  ('7192be68-cfc1-5f58-a588-fb2922b5ca8d', 'shimla/mall-road-walk', 'shimla', 'Most of the centre is uphill on foot', 'Private vehicles are restricted on the Mall and the Ridge, so a hotel that looks central on the map may still mean a steep walk with bags. There is a public lift between the Cart Road and the Mall.', 'accessibility', 'The Ridge', 31.1043, 77.1752, null, null, 'Check how you''ll reach your stay from the nearest drop-off point.', null, 193),
  ('14d7b390-fd11-5d83-93cf-f14a78aaa130', 'chopta/tungnath-winter', 'chopta', 'Tungnath''s doors close for winter', 'Like the other Panch Kedar shrines, Tungnath closes for the winter months and the deity is moved down the valley. The trail can still be walked in snow, but conditions and facilities are very different.', 'planning', 'Tungnath temple', 30.4895, 79.2154, null, null, 'Check the temple''s opening dates if the darshan matters to you.', 'In snow, microspikes and a local guide make the climb much safer.', 194),
  ('bff32612-af29-562e-a2dd-0c84ce9e6f74', 'bhitarkanika/breeding-closure', 'bhitarkanika', 'The park closes for crocodile breeding season', 'Bhitarkanika closes to visitors for a few months each year during the crocodile breeding season, usually covering the early monsoon. Boat trips are the only way in, so there''s no workaround.', 'planning', 'Bhitarkanika boat jetty', 20.723, 86.87, null, null, 'Check the closure dates with the forest department before travelling.', null, 195),
  ('fb7272d7-6244-5a4d-a1d3-205fe2c135ad', 'badami/aihole-pattadakal', 'badami', 'Hire a car for Aihole and Pattadakal', 'Aihole and Pattadakal are close to Badami but public buses are infrequent. Seeing all three on public transport takes much of a day of waiting.', 'transport', 'Pattadakal', 15.948, 75.816, null, null, 'Hire a car or auto for the day to see both.', null, 196),
  ('0c9792b8-4e80-5ca4-954f-15f3712611ac', 'fort-kochi/ferry', 'fort-kochi', 'Take the ferry across the harbour', 'Road traffic between Ernakulam and Fort Kochi can be slow. Ferries and the Kochi Water Metro cross the harbour quickly and are part of the experience.', 'transport', 'Fort Kochi jetty', 9.967, 76.243, null, null, 'Use the water routes instead of a long taxi ride.', null, 197),
  ('f13da7cf-6380-59ae-bf74-45786efc0bbb', 'lonavala/monsoon-weekends', 'lonavala', 'Waterfalls and dams are risky in heavy rain', 'Monsoon weekends bring large crowds to Lonavala''s waterfalls and dam overflows. Water levels can rise suddenly, and authorities restrict access at some spots after heavy rain.', 'safety', 'Bhushi Dam', 18.7425, 73.392, null, null, 'Stay out of flowing water and follow any closures.', null, 198),
  ('a500f06d-c1d9-5491-a431-9b46da1012b1', 'bir-billing/flying-weather', 'bir-billing', 'Flights depend on the sky, not your booking', 'Tandem paragliding is weather-dependent and stops during the monsoon. Even in season, wind can ground flights for a morning or a whole day.', 'weather', 'Billing take-off site', 32.0627, 76.723, null, null, 'Keep a spare day in Bir if the flight is the reason you came.', 'Ask how the operator handles cancelled flights before you pay, and check they are registered with the local authorities.', 199),
  ('66af9fd8-4c29-5fa9-b526-47530bbd1d0f', 'nainital/parking-shuttle', 'nainital', 'Leave the car outside town in peak season', 'During summer holidays the roads into Nainital back up and parking near the lake fills early. Authorities sometimes stop vehicles at the edge of town and run shuttles in.', 'transport', 'Mall Road', 29.3919, 79.4542, null, null, 'Arrive early in the day, or plan to park outside and walk.', null, 200),
  ('d3abfec4-9aca-5f18-9276-0c4324f5eea3', 'thekkady/boat-tickets', 'thekkady', 'Periyar boat tickets go early', 'Boat trips on Periyar Lake have limited capacity, and the early sailings are popular for wildlife. Late arrivals can find the day''s tickets gone.', 'planning', 'Periyar Lake boat landing', 9.57, 77.17, null, null, 'Book online or get to the counter early.', null, 201)
) as v(id, seed_key, destination_slug, title, body, category, place_name, latitude, longitude,
       travel_month, challenge, lesson, advice, ord)
join public.destinations d on d.slug = v.destination_slug
on conflict (id) do update set
  title = excluded.title,
  body = excluded.body,
  category = excluded.category,
  place_name = excluded.place_name,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  travel_month = excluded.travel_month,
  challenge = excluded.challenge,
  lesson = excluded.lesson,
  advice = excluded.advice
where s.source = 'editorial'
  and (s.title, s.body, s.category, s.place_name, s.latitude, s.longitude,
       s.travel_month, s.challenge, s.lesson, s.advice)
      is distinct from
      (excluded.title, excluded.body, excluded.category, excluded.place_name,
       excluded.latitude, excluded.longitude, excluded.travel_month,
       excluded.challenge, excluded.lesson, excluded.advice);

commit;
